// Renders every .apache-chart on the page.
//
// Legacy charts (apache-chart.html, 2025 and earlier posts) render with ECharts' default theme and take
// their title from the figcaption.
//
// Survey charts (survey-chart.html, marked data-survey-chart) are generated by survey-platform's analysis
// build. Their figcaption stays HTML only, they follow the site's light/dark theme, and they are only
// initialised when scrolled near, because a report holds dozens of them.

const THEMES = {
  light: {
    color: ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300", "#6250d6", "#e34948"],
    ink: "#0b0b0b", secondary: "#52514e", muted: "#898781", grid: "#e1e0d9", axis: "#c3c2b7", surface: "#fcfcfb",
  },
  dark: {
    color: ["#3987e5", "#d95926", "#199e70", "#c98500", "#d55181", "#008300", "#9085e9", "#e66767"],
    ink: "#f0efec", secondary: "#c3c2b7", muted: "#898781", grid: "#2c2c2a", axis: "#383835", surface: "#1a1a19",
  },
};

for (const [name, t] of Object.entries(THEMES)) {
  const axis = {
    axisLine: { lineStyle: { color: t.axis } },
    axisTick: { lineStyle: { color: t.axis } },
    axisLabel: { color: t.ink },
    splitLine: { lineStyle: { color: t.grid } },
    nameTextStyle: { color: t.ink },
  };
  echarts.registerTheme(`survey-${name}`, {
    color: t.color,
    backgroundColor: "transparent",
    textStyle: { color: t.ink, fontFamily: "system-ui, -apple-system, 'Segoe UI', 'Noto Sans JP', sans-serif" },
    legend: { textStyle: { color: t.ink }, pageTextStyle: { color: t.ink } },
    tooltip: { backgroundColor: t.surface, borderColor: t.axis, textStyle: { color: t.ink } },
    categoryAxis: axis,
    valueAxis: axis,
    label: { color: t.ink },
    pie: { label: { color: t.ink }, itemStyle: { borderColor: t.surface } },
    bar: { itemStyle: { borderColor: t.surface } },
    sankey: { label: { color: t.ink } },
    visualMap: { textStyle: { color: t.ink } },
  });
}

function isDark() {
  const theme = document.documentElement.dataset.theme;
  if (theme === "dark") return true;
  if (theme === "light") return false;
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

const instances = new Map(); // element -> echarts instance

const sources = new WeakMap(); // element -> its options JSON; echarts.init empties the element, script included

function render(el) {
  try {
    if (!sources.has(el)) sources.set(el, el.querySelector("script").textContent);
    const options = JSON.parse(sources.get(el));
    const survey = "surveyChart" in el.dataset;
    if (!survey) {
      const title = el.parentElement.querySelector("figcaption")?.textContent;
      const subtext = el.dataset.subtext;
      if (title) {
        options.title = { text: title, left: "center" };
        if (subtext) options.title.subtext = subtext;
      }
    }
    instances.get(el)?.dispose();
    const chart = echarts.init(el, survey ? `survey-${isDark() ? "dark" : "light"}` : null);
    chart.setOption(options);
    instances.set(el, chart);
  } catch (e) {
    console.error("Failed to initialize chart:", e, el);
  }
}

const lazy = "IntersectionObserver" in window
  ? new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (!entry.isIntersecting) continue;
      lazy.unobserve(entry.target);
      render(entry.target);
    }
  }, { rootMargin: "400px 0px" })
  : null;

for (const el of document.querySelectorAll(".apache-chart")) {
  if (lazy && "surveyChart" in el.dataset) lazy.observe(el);
  else render(el);
}

// Theme changes repaint survey charts that have already rendered.
function retheme() {
  for (const el of instances.keys()) {
    if ("surveyChart" in el.dataset) render(el);
  }
}
new MutationObserver(retheme).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
window.matchMedia("(prefers-color-scheme: dark)").addEventListener?.("change", retheme);

window.addEventListener("resize", () => {
  for (const chart of instances.values()) chart.resize();
});
